sealed class SkException: kotlin.Exception() {
    
    class Db(
        
        val `reason`: kotlin.String
        ) : SkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Net(
        
        val `reason`: kotlin.String
        ) : SkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Package(
        
        val `reason`: kotlin.String
        ) : SkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SkException> {
        override fun lift(error_buf: RustBuffer.ByValue): SkException = FfiConverterTypeSkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSkError : FfiConverterRustBuffer<SkException> {
    override fun read(buf: ByteBuffer): SkException {
        

        return when(buf.getInt()) {
            1 -> SkException.Db(
                FfiConverterString.read(buf),
                )
            2 -> SkException.Net(
                FfiConverterString.read(buf),
                )
            3 -> SkException.Package(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SkException): ULong {
        return when(value) {
            is SkException.Db -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SkException.Net -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SkException.Package -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SkException, buf: ByteBuffer) {
        when(value) {
            is SkException.Db -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SkException.Net -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SkException.Package -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}




